using System.Text.Json.Serialization;

namespace MatDesign.Core;

/// <summary>How binding a rule is. Stored by name ("Must"), so a file of the Studio can be read by a person.</summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum RuleLevel
{
    /// <summary>Every Mat app does this. Breaking it is a bug.</summary>
    Must,

    /// <summary>The default. Deviate only with a reason that is written down.</summary>
    Should,

    /// <summary>Allowed and recommended where it fits.</summary>
    May,
}

/// <summary>A group of rules that belong together.</summary>
public sealed record RuleArea(string Id, string Name, string Icon, string Summary);

/// <summary>
/// One rule of the design system. <see cref="Source"/> says where it comes from (the owner's own words, or the app whose documentation
/// already had it), <see cref="Check"/> whether a test of this repository enforces it or a reviewer has to.
/// </summary>
public sealed record Rule(
    string Id,
    string Area,
    string Title,
    string Statement,
    RuleLevel Level,
    string Source,
    string? Why = null,
    string? Do = null,
    string? Dont = null,
    string Check = "Review");

/// <summary>
/// The rulebook of the Mat family: every rule about how an app looks and behaves, with a stable id (<c>SHELL-03</c>) that code reviews,
/// commit messages and agents can cite. Rules that the owner stated in their own words are marked with the source "Owner".
/// </summary>
public static class RuleBook
{
    public const string Owner = "Owner";
    public const string MatSplit = "MatSplit ui-controls";
    public const string MatmonCloud = "Matmon.Cloud ui-conventions";
    public const string Matthix = "Matthix UI guide";
    public const string MatCms = "MatCMS";
    public const string MatMail = "MatMail";
    public const string Mattiverse = "Mattiverse";
    public const string MatPaper = "MatPaper";
    public const string Design = "MatDesign";

    /// <summary>The source of a rule that was written in the Studio.</summary>
    public const string Studio = "Studio";

    public static IReadOnlyList<RuleArea> Areas { get; } =
    [
        new("IDENT", "Identity", "palette", "What makes an app a Mat app and what makes it its own: the accent, the logo, the name."),
        new("SHELL", "Shell", "sidebar", "The frame around every page: menu, logo, theme button, user, version, breadcrumb."),
        new("LIST", "Lists and galleries", "list", "Toolbar, search, filter, sort, table, pagination, actions: in a fixed order."),
        new("FORM", "Forms", "edit", "Create and edit pages: fields, validation, and the buttons below the content."),
        new("BUTTON", "Buttons", "play", "Four kinds, one primary, always positive to negative."),
        new("DIALOG", "Dialogs", "message-square", "Every question and every list tool is a dialog; on a phone it is full screen."),
        new("TABLE", "Tables", "table", "Cells, numbers, status, selecting rows, and the card layout on a phone."),
        new("COLOR", "Colour and themes", "palette", "Tokens only, light and dark, status colours, contrast."),
        new("TYPE", "Typography", "type", "System fonts, a scale, mono for technical values."),
        new("SPACE", "Space and shape", "layers", "The 4 px scale, radii, elevation, motion."),
        new("ICON", "Icons", "star", "One sprite, inline, no font, no CDN, no emoji."),
        new("MOBILE", "Phones", "smartphone", "Mobile is not an afterthought: what changes below 900 px."),
        new("A11Y", "Accessibility", "accessibility", "Keyboard, focus, contrast, motion, labels, language, states, live regions, loading."),
        new("CODE", "Markup and code", "code", "One code base per control, no inline styles, no outside resources, the names and texts of the script, what finished means."),
    ];

    public static IReadOnlyList<Rule> All { get; } =
    [
        // ------------------------------------------------------------------------------------------------ IDENT
        new("IDENT-01", "IDENT", "One colour per app",
            "Every app has its own accent colour, and it is the only colour an app chooses. It is set once, as `--mat-app-accent` on `<html data-app=\"...\">`; hover, tint, link colour and focus ring are derived from it in both modes. Everything else (layout, shapes, type, status colours) is the shared design.",
            RuleLevel.Must, Owner,
            Why: "\"Every app has its own colours, but the design is basically the same: the same identity.\"",
            Do: "<html data-app=\"matmail\">", Dont: "a second brand colour in the app's CSS", Check: "Test"),
        new("IDENT-02", "IDENT", "The accent carries its text",
            "White text on the accent reaches WCAG AA (4.5:1). If the accent is too light for that, the app sets `--mat-app-on-accent` to a dark colour instead. Dark mode lightens the accent and always uses dark text on it; that is checked for every app.",
            RuleLevel.Must, Design, Do: "darken the accent a little, or use dark text on a light accent", Check: "Test"),
        new("IDENT-03", "IDENT", "Logo and accent belong together",
            "The main colour of the app's logo is the app's accent. The logo is a rounded square (radius about 22 %) with one glyph, drawn in the flat accent colour with the glyph from the icon sprite.",
            RuleLevel.Should, Design, Why: "A user who sees the logo and then the UI should see one colour."),
        new("IDENT-04", "IDENT", "No two apps look alike",
            "Two apps do not share an accent, and no two accents are closer than the distance the palette check allows (0.45 in OKLab x 10). Look at the colour of a small logo or an active tab: if it can be mistaken for another app, it is too close.",
            RuleLevel.Should, Design, Check: "Report (Identity > Palette)"),
        new("IDENT-05", "IDENT", "The user may pick an accent",
            "An app may let a user choose their own accent from the presets (purple, indigo, ocean, teal, forest, gold, sunset, red, berry, graphite). The choice is stored per user and written as `data-accent` on `<html>`; it wins over the app colour. Components never read the accent from anywhere else.",
            RuleLevel.May, MatPaper, Why: "MatPaper, Matdo and MatMail already offer a choice; this makes it the same ten everywhere."),
        new("IDENT-06", "IDENT", "The name",
            "An app is written exactly as in the registry (MatMail, Matcad, Matddns ...), in the menu header, the browser title (`Page · App`), the manifest and the README.",
            RuleLevel.Must, Design),
        new("IDENT-07", "IDENT", "The tab title",
            "The browser title is `Page title · App name`. A detail page puts the entity first (`Invoice 2026-04 · Documents · MatPaper`).",
            RuleLevel.Should, MatPaper, Check: "Test (the title of every page of this site is Page title, a dot and the site name)"),
        new("IDENT-08", "IDENT", "The files of a brand are its own, checked by content, with alt text",
            "A brand's logo, word mark, favicon, app icon and fonts are files of its own: they live in its volume under their SHA-256, are served from its own site, are written into every release under `brand/` and are never loaded from another site (CODE-03). A file is accepted by what is inside it (a PNG, an ICO, a WOFF2, a WOFF, or an SVG that parses as XML), never by its name or the type a browser reports, within limits: SVG 100 KB, PNG 500 KB and 2048 px, ICO 200 KB, a font 400 KB, at most 12 faces in 3 families. An SVG is read against a list of allowed elements and attributes: no script, foreignObject, style element, event handler, entity, `javascript:` or `data:` address, and no reference that leaves the file. A logo and a word mark always have an alt text (A11Y-03), and may have a variant for dark surfaces. A font family has a name of its own (not a generic family, not one the toolkit's stacks use) and is declared with `font-display: swap`. Files are never overwritten or deleted, so every revision of the brand can be restored; a brand without assets writes nothing.",
            RuleLevel.Must, Owner, Why: "An uploaded file is the one place where a stranger's bytes enter the site: an SVG can carry a script, anything can be named like a picture. Content, an allowlist and immutable files keep a brand from endangering the site and every release self-contained (docs/PRODUCT.md, decided by the owner on 2026-10-14).",
            Do: "<img class=\"mat-brandmark\" src=\"/ui/brand/logo-1a2b3c4d5e.svg\" alt=\"Acme\">, @font-face { font-display: swap; src: url(\"brand/fonts/acme-400-normal-1a2b3c4d5e.woff2\") format(\"woff2\"); }", Dont: "a logo or a font loaded from a CDN, an SVG with a script or an onload, a file trusted because of its name, a logo without alt text, a file replaced under the same name", Check: "Test (validator, store, serving, release) and browser"),

        // stage 14 of docs/PRODUCT.md (demo data and templates)
        new("IDENT-09", "IDENT", "A program names its surfaces after its company",
            "The program that runs a design system names its own surfaces after the company that runs it, never after another company. The name under the logo, the title of every page, the footer, the version line, the sign-in and setup pages, and the README, the styleguide and the changelog of a release read the names of the company (company, short name, site name, tagline: the tenant) and never a name written into the code. The Mat apps, their accents, the audit of their repositories and the Mat brand are a template, the demo, that a company can start from, look at and change; the demo is not the default identity of every instance. A company that starts blank sees its own name and none of the Mat apps. The toolkit's own names (`MatUi`, the prefix `mat-`) are the toolkit's and not a company's.",
            RuleLevel.Must, Owner,
            Why: "MatDesign is software in which any company builds its own branding, toolkit and CI/CD (docs/PRODUCT.md). A site that says Mat on every page of another company is that company's site with the wrong name on it. Decided by the owner on 2026-10-14.",
            Do: "@Design.Tenant.SiteName in the footer, ShellModel.Site(design) for the shell", Dont: "a literal MatDesign in a page, a footer or a README",
            Check: "Test (a blank start shows its own names and none of the Mat apps)"),

        // ------------------------------------------------------------------------------------------------- SHELL
        new("SHELL-01", "SHELL", "The menu is on the left, the logo above it",
            "The menu is always on the left. At its top is the logo with the app name; clicking it leads to the start page.",
            RuleLevel.Must, Owner, Do: "<aside class=\"mat-nav\"> brand, scroll area, foot </aside>", Check: "Test (the menu and the logo are on every page of this site) and browser"),
        new("SHELL-02", "SHELL", "Menu items",
            "A menu item is an icon and a label. The current page is marked (`aria-current=\"page\"`): a tint of the accent behind the whole item and the accent on its icon, never a bar at one edge (COLOR-08). Related items are grouped under short headings in sentence case. A count goes into a badge at the right end of the item. A heading can carry one small icon action at its right end (a gear to manage the list below it, a plus to add to it) instead of a \"Manage\" or \"New\" item below the list: a link or a button that opens a menu, with a name for screen readers (`aria-label`). A link that leads to the current page is marked like a current item.",
            RuleLevel.Should, Mattiverse),
        new("SHELL-03", "SHELL", "The foot of the menu",
            "At the bottom of the menu, in this order from top to bottom: the 3-state theme button together with the user, and below them the version. Nothing else lives down there, except the menu switcher, which an app may put directly above the user (SHELL-15).",
            RuleLevel.Must, Owner, Do: "([ menu switcher ], only where the app puts it here)\n[ user (avatar, name, role) ][ theme button ]\nversion", Check: "Test (browser: the user and the theme button side by side, the version below them)"),
        new("SHELL-04", "SHELL", "The theme button has three states",
            "It is one icon button that cycles System, Light, Dark and shows the icon of the current state (monitor, sun, moon). Its label and tooltip name the current state and the next one. The choice is saved (per user on the server when there is an account, otherwise in the browser). System means no `data-theme` attribute: the page follows the operating system.",
            RuleLevel.Must, Owner, Check: "Test (script)"),
        new("SHELL-05", "SHELL", "The user opens a context menu",
            "The user (avatar, name, role) is a button. A click opens a context menu with the things of the account: show account, other personal settings, and Sign out as the last item. The menu opens upwards from the button and closes on Escape, on a click outside and on selecting an item.",
            RuleLevel.Must, Owner, Do: "Account · Settings · (separator) · Sign out", Check: "Test (the user is on every page of this site) and browser"),
        new("SHELL-06", "SHELL", "The version is in the menu",
            "Below the user the menu shows the app name and its version in the mono font, small and muted: `MatMail 1.4.212-20261010`. Release, nightly and local builds use the version format of the project (`1.4.212-20261010`, `nightly-212-20261010`, `local-20261010`).",
            RuleLevel.Must, Owner, Check: "Test (the version is on every page of this site)"),
        new("SHELL-07", "SHELL", "The menu scrolls on its own",
            "The menu and the content scroll separately. The page itself never scrolls; the logo and the foot of the menu stay in place while the items in between scroll.",
            RuleLevel.Must, Owner, Do: ".mat-app is as high as the window; .mat-nav__scroll and .mat-main scroll", Check: "Test (browser: the page does not scroll, the menu and the content do)"),
        new("SHELL-08", "SHELL", "A breadcrumb above every page",
            "The content always has a breadcrumb above it: `Section / Page / Detail`. The last item is the current page and not a link; the others lead back. A back button in the page header is not needed.",
            RuleLevel.Must, Owner, Do: "<nav class=\"mat-crumbs\"><ol>...</ol></nav>", Check: "Test (every page of this site has a breadcrumb)"),
        new("SHELL-09", "SHELL", "The page head",
            "Under the breadcrumb a page starts with the title (h1) and, optionally, a line of explanation. There is no icon tile next to the title. Actions do not belong in the page head: see FORM-01 and LIST-07.",
            RuleLevel.Should, Mattiverse),
        new("SHELL-10", "SHELL", "The page width",
            "Content is at most 1240 px wide and has a side padding of 16 to 32 px. Forms and reading pages use the narrow variant (780 px).",
            RuleLevel.Should, Matthix),
        new("SHELL-11", "SHELL", "Pages without a menu",
            "Sign-in, setup and error pages have no menu: a centred card on the plain page background with the logo above the title.",
            RuleLevel.Should, Design),
        new("SHELL-12", "SHELL", "Messages after a save",
            "After a successful POST the page redirects (PRG) and says what happened: a toast (at the bottom right, gone after a few seconds, with an X) for \"done\", an alert at the top of the content for something the user has to read. A toast is never the only place for an error or for something the user has to act on, because it goes by itself. Errors stay on the page, at the field and in a summary.",
            RuleLevel.Should, MatSplit, Check: "Test (the toasts live in the topmost dialog) and review"),
        new("SHELL-13", "SHELL", "Submenus",
            "A menu can be hierarchical, one level deep. The parent is a button, not a page: it opens its children (`aria-expanded`, `aria-controls`). If the section has a page of its own, that page is its first child. The branch that has the current page is open when the page loads; what the user opens or closes is remembered. Children show no icon. A closed parent shows the sum of its children's badges.",
            RuleLevel.Must, Owner, Why: "Apps with many pages stay readable, and the current page is never hidden in a closed branch.", Do: "<li class=\"mat-nav__branch\"><button class=\"mat-nav__item mat-nav__parent\" data-nav-branch=\"items\" aria-expanded=\"false\">...</button><div class=\"mat-nav__sub\">...</div></li>", Dont: "a parent that is a link, a third level, a branch that hides the current page", Check: "Test (markup contract, script) and browser"),
        new("SHELL-14", "SHELL", "Badges in the menu",
            "A menu item can carry a badge at its right end: a count (above 99 it reads `99+`) or a dot for \"something new\". The tone follows the status colours (COLOR-03): the accent for a plain count, amber for something to look at, red for something that failed, green and blue for information, grey for a neutral number. A badge has a text for screen readers (\"3 invitations pending\"). The colour is never the only information (COLOR-04).",
            RuleLevel.Must, Owner, Do: "<span class=\"mat-nav__badge mat-nav__badge--warn\">3<span class=\"mat-sr-only\"> to review</span></span>", Check: "Test (markup contract) and browser"),
        new("SHELL-15", "SHELL", "More than one menu",
            "An app with distinct areas, such as an administration, has one menu per area. The switcher shows the name of the current menu; a click opens a context menu with all menus, the current one checked. Choosing one swaps the items, or, when the menu has a start page (its entry is a link), loads that page, which shows its own menu. The switcher sits under the logo, at the foot above the user, or both; with a main action (SHELL-19) it may sit at the end of the menu (`mat-nav__switch--end`); from the foot and the end the popup opens upwards. The menu with the current page is shown on load. It appears only with two menus or more; a menu the user may not use is not offered. While another menu is shown, a dot says that this one needs attention. A parent entry opens its children, one level deep like SHELL-13: several menus (People, System) or the choices of a context that changes what the whole app shows (the tenant: a button each that posts, the current one checked). The administration stands last, below the choices. A parent is a button (`aria-expanded`, `aria-controls`), not a menu; the group with the current menu is open on load.",
            RuleLevel.Must, Owner, Why: "An administration has its own pages, its own groups and its own badges, and does not clutter the menu of everyday work. Where the switcher sits is the app's choice: under the logo it is the first thing, above the user it is in reach of the thumb on a phone. Many menus stay readable when they are grouped.", Do: "[ logo, name ]\n[ switcher: Work v ]   (or at the foot, above the user)\nitems of the current menu\n([ switcher ])\n[ user ][ theme button ]\nversion", Dont: "a parent that is itself a menu, a third level, a switcher at the foot that opens downwards", Check: "Test (markup contract, script) and browser"),
        new("SHELL-16", "SHELL", "Long pages have an index",
            "A page with many sections, such as documentation, a long settings page or a long form, has an index beside the content (\"On this page\"): a sticky list of links to the sections, with the section in view marked, so that one click jumps there instead of many clicks through pages. From 1100 px the index is a column beside the content; below that an icon at the right end of the header bar (SHELL-17) opens the same list in a dialog (full screen on a phone), so it is in reach however far the page is scrolled. A short page needs no index.",
            RuleLevel.Should, Owner, Why: "Reading a long page and jumping around in it is faster than opening one page per section.", Do: "<div class=\"mat-with-toc\"> <div class=\"mat-with-toc__main\">...</div> <aside class=\"mat-toc-aside\"><nav class=\"mat-toc\" data-scrollspy>...</nav></aside> </div>", Check: "Test (markup contract, script) and browser"),
        new("SHELL-17", "SHELL", "Icons at the right of the header bar",
            "The bar above the content (the breadcrumb) may carry icon buttons at its right end, for things that belong to the whole app and not to one page: search, notifications, help, a language or a status. Icons only, each with a name for screen readers and a tooltip (ICON-03). A count or a dot goes in a small badge on the icon, in the colours of the status (COLOR-03). The main action of the app (scan a document, add something) may be highlighted: a filled accent button (`mat-btn--primary`) instead of a ghost one, last, at the right end. A second action that should be seen but is not the main one may be a secondary icon button (`mat-btn--secondary`), so that only one icon has the accent colour. At most four; anything more goes behind one icon that opens a menu. Never actions of the page (FORM-01, LIST-07) and never the theme button or the user (SHELL-03); the one thing of a page that belongs here is its index (SHELL-16), where that is not drawn beside the content. On a phone they stay and the breadcrumb gives way.",
            RuleLevel.Should, Owner, Why: "The bar is the one place that is on every page; things of the app that the user wants at hand everywhere belong there, and page actions stay with their content.", Do: "<div class=\"mat-topbar__actions\"> icon buttons (mat-btn--ghost mat-btn--icon; one mat-btn--primary for the main action, mat-btn--secondary for a second one), a badge as the last child </div> after the breadcrumb", Dont: "text buttons, Save or Create in the bar, more than four icons, more than one icon in the accent colour, an icon without a name", Check: "Test (markup contract) and browser"),
        new("SHELL-18", "SHELL", "The footer",
            "A page may end with a footer: on the left what the app is (name, copyright, a status), on the right the links that belong to every page (imprint, privacy, help, contact). It comes after the content at the end of the scrolling area, is never fixed over the content, and lines up with the content width. On a page without a menu it sits under the card, centred. The version stays in the menu (SHELL-06); a footer is not needed on pages that are only a tool inside an app.",
            RuleLevel.Should, Owner, Why: "Legal links and contact have a fixed place that is found without searching, and the page ends instead of just stopping.", Do: "<footer class=\"mat-footer\"><p class=\"mat-footer__text\">...</p><ul class=\"mat-footer__links\">...</ul></footer>", Dont: "a footer that is fixed to the window, the theme button or the user in the footer, a second menu", Check: "Test (markup contract) and browser"),
        new("SHELL-19", "SHELL", "A main action in the menu",
            "An app that is mostly used for one thing (add a document, write a message, create an item) may put that action at the top of its menu, as the first item, filled with the accent (`mat-nav__item--primary`): an icon and a label, a link to the page that does it. There is one per app, in the menu of the everyday work, and it carries no badge. On its own page it stays filled, a step darker, like the current item of a menu (SHELL-02).",
            RuleLevel.Should, Owner, Why: "What the user comes for is found without reading the menu, and it is the one filled thing in it.", Do: "<a class=\"mat-nav__item mat-nav__item--primary\" href=\"/add\"><svg class=\"mat-icon\">...</svg><span>Add document</span></a>", Dont: "two filled items, a filled item in a submenu or below other items, a filled item with a badge, a main action that only lives in the header bar", Check: "Test (CSS, markup contract) and browser"),

        // -------------------------------------------------------------------------------------------------- LIST
        new("LIST-01", "LIST", "List page and edit page",
            "CRUD is a list and a separate page for creating and editing. No inline editing, no modal for create or edit. A list page may open dialogs only for its own tools (LIST-03).",
            RuleLevel.Must, Owner, Why: "Reads the same on a phone, can be linked to, and survives a reload."),
        new("LIST-02", "LIST", "The toolbar is always above",
            "Every list and every gallery has a toolbar above it, without exception. Nothing else sits between the toolbar and the list except the applied filters. A list is a collection of items the user searches, opens or edits; a table that only presents a few fixed facts (a comparison, a report of fewer than ten rows, a chart's data) is not a list and needs no toolbar.",
            RuleLevel.Must, Owner, Do: "<div class=\"mat-toolbar\"> Search, Filter, Sort ... </div>", Check: "Test (markup contract)"),
        new("LIST-03", "LIST", "Search is a button or a field; filter and sort are buttons that open dialogs",
            "In the toolbar Filter and Sort are separate buttons. Each opens a dialog with its own fields; selects, date ranges and the like are never placed in the toolbar. Search is either a third button that opens a dialog, or, where searching is the main thing to do with the list, a search field directly in the toolbar at its left, and then the dialog buttons stand together at the right end. Whatever the form, everything is sent as one GET request, so the result is a link that can be shared. On a phone the field takes the first row, the buttons stand right-aligned in the next, and the dialogs are full screen (DIALOG-03).",
            RuleLevel.Must, Owner, Why: "Searching is the most common thing to do with a list and wants a field at hand; filter and sort have several fields each and belong in a dialog.", Do: "<div class=\"mat-toolbar\"><div class=\"mat-input-icon mat-toolbar__search\">icon, input type=search</div><span class=\"mat-toolbar__spacer\"></span><div class=\"mat-toolbar__end\">Filter, Sort</div></div>", Dont: "selects or a date range directly in the toolbar, a search field and a search dialog side by side, a field in the toolbar that is not part of the GET form", Check: "Test (the toolbar with its dialogs and one GET form) and browser"),
        new("LIST-04", "LIST", "A tool in effect is visible",
            "A search, a filter or a sort that is in effect is shown on its button (highlighted, with the term, the number of filters or the sort field); a search field shows its term itself. The applied filters may also be shown as removable chips under the toolbar.",
            RuleLevel.Should, Design),
        new("LIST-05", "LIST", "The order of a list",
            "Fixed order from top to bottom: toolbar, applied chips, table or gallery, empty state, pagination, list actions. The control enforces the order, whatever the markup order.",
            RuleLevel.Must, MatSplit, Check: "Test (browser: the toolbar is above the table, the pagination directly under it, the actions below)"),
        new("LIST-06", "LIST", "Pagination directly under the table",
            "Pagination sits directly under the table, and nothing else does. It renders nothing when there is one page or none. The page number is read from the query string and is never bound as a route value named `page`.",
            RuleLevel.Must, Owner),
        new("LIST-07", "LIST", "List actions below, left-aligned",
            "Actions that belong to the list as a whole (New, Import ...) stand below it, left-aligned, in one row. A destructive action keeps its distance (it is separated by the spacer).",
            RuleLevel.Must, Owner),
        new("LIST-08", "LIST", "Delete lives on the edit page",
            "Deleting is done on the edit page, not from the list. Where a row still carries a delete button (admin lists), it is the last action of the row and asks for confirmation.",
            RuleLevel.Should, MatSplit),
        new("LIST-09", "LIST", "Row actions",
            "A row opens its edit page through the title. Further actions are icon buttons with a tooltip at the end of the row (`mat-table__actions`).",
            RuleLevel.Should, Design),
        new("LIST-10", "LIST", "List or gallery",
            "Where a collection can be shown both ways, a segmented control in the toolbar switches between list and gallery. The choice is remembered per list.",
            RuleLevel.May, Design),
        new("LIST-11", "LIST", "The empty state",
            "An empty list shows an icon, a title, a sentence and the primary action that fills it. An empty result of a search says so and offers to reset the tools. " +
            "The empty state stands where the rows would be, in the same frame as the table (`.mat-list > .mat-empty`); outside a list `mat-empty--framed` gives it that frame, inside a card it has none. " +
            "When the list has nothing yet (not: nothing matches), the empty state is `mat-empty--first` and holds the primary action; the toolkit then hides the same primary button in the actions row below, so it is not there twice.",
            RuleLevel.Should, MatSplit),
        new("LIST-12", "LIST", "Counts",
            "The toolbar shows how many items the list has (and how many match, when a tool is in effect).",
            RuleLevel.May, Design),
        new("LIST-13", "LIST", "A carousel for what is looked at one after another",
            "Pictures, the steps of a tour or a few cards that are looked at one after another may be shown as a carousel: a strip of slides that scrolls and snaps, with Previous and Next buttons and one dot per page below it. Without the script it is a strip you scroll. It never moves by itself unless the author asks for it; then it has a Pause button, waits while the pointer or the focus is inside and does not start for a user who asked for less motion (A11Y-05). The region is named, every slide says which one of how many it is, the slides that are out of view cannot be reached with the Tab key, and a screen reader is told which page is shown. What people search, sort or compare is a list or a table (LIST-01), not a carousel.",
            RuleLevel.May, Design, Why: "A strip that people swipe is familiar on a phone, but a show that moves by itself, hides content behind a control that nobody finds or traps the keyboard is worse than a row of cards.", Do: "<section class=\"mat-carousel\" data-carousel aria-label=\"Tour\"><div class=\"mat-carousel__track\"><div class=\"mat-carousel__slide\">...</div></div></section>", Dont: "a show that starts by itself and cannot be paused, the one important thing on the third slide, a carousel for a list that people search", Check: "Test (markup contract, script) and browser"),
        new("LIST-14", "LIST", "A schedule for events in time",
            "Events that happen at a time (appointments, deadlines, a school year) may be shown as a schedule: an agenda that lists them by day under headings that stay at the top, and a day, a week, a month and a year, switched by a row of buttons. It pages by the unit of the view with Previous and Next, the arrow keys, PageUp and PageDown and a swipe, has a Today button and a title that names the period (with the calendar week, ISO 8601, where weeks matter). An event is a link or a button; its tone is always told by an icon and a text as well (COLOR-04) and drawn as a tint with a line all around, never a bar at one side (COLOR-08). Days and months are in the language of the page, today is marked, a screen reader is told the period after every page and the focus stays on the control used. On a phone a week is a row per day and a month a compact grid, targets are 44 px (MOBILE-04) and nothing scrolls sideways; with reduced motion nothing slides (A11Y-05). An app that loads events for what is visible is told what that is, and a loading state shows until they arrive. Picking a date is a date picker (FORM-15), what people search or sort is a table (LIST-01).",
            RuleLevel.May, Design, Why: "Events in time are read by day and week, and a list sorted by date cannot show that two appointments overlap, that a week has a gap or how busy a month is; people also expect to swipe or press an arrow to the next period.", Do: "<section class=\"mat-schedule\" data-schedule aria-label=\"Practice\" data-view=\"agenda\" data-events='[{\"id\":\"a1\",\"title\":\"Check-up\",\"start\":\"2026-10-12T09:00\",\"tone\":\"ok\"}]'></section>", Dont: "a tone that is only a colour, a week grid that makes a phone scroll sideways, a schedule that moves by itself, a schedule to pick a date", Check: "Test (markup contract, script) and browser"),
        new("LIST-15", "LIST", "Lists of rows",
            "Things that are looked at, opened, switched or ticked off one by one, as in a phone app (contacts, messages, settings, files, tasks, notifications), are a list of rows: `mat-itemlist` of `mat-item`. A row has a lead (an avatar, an icon, a thumbnail or a check), a title with up to two lines under it and an end (a note, a count, a value, the arrow). The whole row is the target (a link, a button or a label) and at least 48 px high (MOBILE-04); what has to be pressed as well (a switch, a button, a handle) stands beside it and never inside it. A state is told in more than a colour (COLOR-04): unread is bold with a dot, done is struck through, a tone has its own icon. What is selected is a tint behind the whole row (COLOR-08). Actions that appear when a row is swiped can be reached without a swipe (a More button and the arrow keys, A11Y-02) and are out of the tab order while they are hidden; a row that can be moved has a handle that works with the pointer and with the keyboard (Space, arrow keys, Escape) and says what it does to a screen reader. What people search, sort and compare in many columns is a table with a toolbar (LIST-02), not a list of rows.",
            RuleLevel.Should, Design, Why: "People know this list from their phone: one row, one target, the thing at its end tells what it does. A swipe that is the only way to an action, a switch inside a link or a state that only a colour tells is a row that some people cannot use.", Do: "<ul class=\"mat-itemlist\" data-itemlist><li class=\"mat-item\"><a class=\"mat-item__main\" href=\"#\"><span class=\"mat-item__lead\">...</span><span class=\"mat-item__body\"><span class=\"mat-item__title\">...</span></span><span class=\"mat-item__end\">...</span></a></li></ul>", Dont: "a button or a switch inside a link, actions that only a swipe reaches, a state that only a colour tells, a bar at one side of the selected row, a list of rows for a table that is searched and sorted", Check: "Test (markup contract, CSS, script) and browser"),
        new("LIST-16", "LIST", "Groups in a table",
            "A table whose rows belong to something (the routes of a domain, the files of a folder, the mailboxes of a provider) is grouped: one `tbody` per group (`mat-group`), its first row is the heading with the name of the group and the number of its rows, and the heading opens and closes the group. The toggle is a button with `aria-expanded` and the name of the group, the closed rows are out of the tab order and what the user opened or closed is remembered; a group that holds a search hit or the current item stays open (`data-group-fixed`). The rows hang on a line below the heading, one level deep (a deeper hierarchy is a tree, not a table). The action that adds a row to a group is the last row of that group (`mat-group__add`), so it is where the eye ends; the action that adds a group, or a row without a group, stays under the list (LIST-07). With many groups a button in the header of the first column opens or closes all of them. On a phone a group is a bar over cards, without the line, and the add row is a card with its button.",
            RuleLevel.Should, Owner, Why: "A long list under headings is easier to read when the headings can be folded, and \"add one more here\" belongs where the group ends, not in its heading, where it competes with the name of the group.", Do: "<tbody class=\"mat-group\" data-group=\"example.org\"><tr class=\"mat-group__head\">...</tr><tr class=\"mat-group__item\">...</tr><tr class=\"mat-group__add\">...</tr></tbody>", Dont: "an add button in the heading of the group, a heading that is not a button, a group that opens and closes without a name for a screen reader, a second level inside a group", Check: "Test (markup contract, CSS, script) and browser"),
        new("LIST-17", "LIST", "A tree view for a hierarchy",
            "Folders, categories and areas, anything that nests to a depth that is not known, are shown as a tree view (`mat-tree`), not as indented table rows, an accordion inside an accordion or a menu. It follows the ARIA tree pattern: `role=\"tree\"` with a name, `treeitem` with `aria-level`, `aria-setsize` and `aria-posinset`, `aria-expanded` on a parent, `group` around children; the whole tree is one Tab stop and Up, Down, Left, Right, Home, End, `*`, Enter, Space and the first letters of a name work as in a file manager. A chosen item is a tint behind the whole row (`aria-selected`, COLOR-08); with several chosen (`data-multiple`, `aria-checked`) a parent is checked when all its items are and shows a dash, not only a colour, when some are (COLOR-04). A filter keeps the parents of a match, open, and says the number of matches. What the user opened is remembered, children that are costly to get are loaded when an item opens, with a loading state. A row is 44 px high on a phone, a long label wraps, nothing scrolls sideways (MOBILE-01, MOBILE-04). A hierarchy of one level is a grouped table (LIST-16), a flat list is a list of rows (LIST-15).",
            RuleLevel.Should, Design, Why: "People know the tree from the file manager and expect to walk it with the arrow keys; a hierarchy drawn any other way hides its depth, and a tree without the roles and the keys cannot be used without a mouse.", Do: "<ul class=\"mat-tree\" data-tree aria-label=\"Files\"><li class=\"mat-tree__item\"><div class=\"mat-tree__row\">...</div><ul class=\"mat-tree__group\">...</ul></li></ul>", Dont: "a tree of buttons that are all in the Tab order, a selected item marked by a bar at its side, a folder in between that is only a colour, a phone row smaller than 44 px", Check: "Test (markup contract, CSS, script) and browser"),

        // -------------------------------------------------------------------------------------------------- FORM
        new("FORM-01", "FORM", "Buttons are always under the content",
            "On every create and edit page the buttons are under the content of the form, never in the page head and never floating beside it. They stand in one row and go from positive to negative: Save, Back, then a gap, then Delete.",
            RuleLevel.Must, Owner, Do: "<div class=\"mat-btn-row\"> Save, Back, spacer, Delete </div>", Dont: "a Save button in the page head or a second, duplicate row", Check: "Test (CSS contract)"),
        new("FORM-02", "FORM", "The order is enforced by the control",
            "`mat-btn-row` orders its buttons itself: primary, then secondary and ghost, then the spacer, then danger. The order of the markup does not matter.",
            RuleLevel.Must, MatSplit, Check: "Test (CSS contract)"),
        new("FORM-03", "FORM", "Labels above, hints below, errors at the field",
            "A field has its label above, its hint below and its error message directly under it. Errors also appear as a summary at the top of the form. The space for the error line is reserved, so the layout does not jump when it appears.",
            RuleLevel.Must, Matthix),
        new("FORM-04", "FORM", "Dependent fields appear when they are needed",
            "A field that only matters for a certain answer is hidden until then (`data-show-if`, `data-show-value`). A hidden field is disabled: it posts nothing and cannot block the form.",
            RuleLevel.Must, Owner, Check: "Test (browser: a dependent field is shown only while it is needed)"),
        new("FORM-05", "FORM", "Validation in the UI, not in the browser",
            "Forms are `novalidate`; the browser's bubbles are not used. Messages are written in the language of the app and come from the model (`ErrorMessage`). Checkboxes are never \"required\". A submit button with `formnovalidate` (Delete, Save as draft) sends the form without the check.",
            RuleLevel.Must, MatSplit),
        new("FORM-06", "FORM", "Required fields",
            "Required fields are marked with an asterisk in the label; optional fields are not marked. A field is either required or says why it is optional in its hint.",
            RuleLevel.Should, MatSplit),
        new("FORM-07", "FORM", "Grid",
            "Fields use a two-column grid on a wide screen and one column on a phone. Long fields (descriptions, text areas) span both columns.",
            RuleLevel.Should, MatSplit),
        new("FORM-08", "FORM", "Every control has an id",
            "Every control has a unique id (several equal controls may share a page); labels point to it with `for`. Names are not prefixed, or model binding breaks.",
            RuleLevel.Must, MatSplit, Check: "Test (every control of an example has an id, ids are unique)"),
        new("FORM-09", "FORM", "No danger zone",
            "There is no panel or tab called \"Danger zone\". A destructive action is the last button of the button row, or it sits in the row it acts on (remove member). It keeps the red accent and asks for confirmation. A reversible switch (pause, disable) is not destructive.",
            RuleLevel.Must, MatmonCloud),
        new("FORM-10", "FORM", "Long forms",
            "On a long form the fields are split into cards or sections with a title each, and the button row sticks to the bottom edge on a phone (`mat-btn-row--sticky`), so Save is always within reach.",
            RuleLevel.May, MatSplit),
        new("FORM-11", "FORM", "Confirm what cannot be undone",
            "Anything that deletes or overwrites data asks first, in a dialog that names the thing (\"Delete backup 12 Oct?\"), with the destructive button last (DIALOG-06).",
            RuleLevel.Must, MatCms),
        new("FORM-12", "FORM", "The right control for the value",
            "A field has the type of its value (`email`, `tel`, `url`, `number`, `date`, `time`, `search`, `password`) and, where it helps, `inputmode` and `autocomplete`, so that a phone shows the right keyboard and a password manager works. Up to five exclusive choices are radios, more are a select; several yes-or-no choices are checks in a group with a legend; a yes-or-no that applies at once is a switch, one that is saved with the form is a check. A range is only for a value whose exact number does not matter, and it shows the number.",
            RuleLevel.Should, Design, Do: "<input class=\"mat-input\" type=\"email\" autocomplete=\"email\">", Dont: "a text field for a date, a select with three options, a switch that needs a Save button"),
        new("FORM-13", "FORM", "Floating labels",
            "A floating label (the label in the field that moves up) may be used in a short form such as a sign-in, never in a long one. It is a real label with `for`; a placeholder is never the only label.",
            RuleLevel.May, Design, Do: "<div class=\"mat-field mat-field--float\"><input class=\"mat-input\" id=\"x\" placeholder=\" \"><label class=\"mat-label\" for=\"x\">Name</label></div>", Check: "Test (toolkit CSS: a floating label needs a space as its placeholder) and review"),
        new("FORM-14", "FORM", "Form layouts",
            "The default is labels above the fields in one or two columns (three or four on a wide screen for short fields). The label beside the field is for settings pages on a wide screen and goes back above below 700 px; an inline form is for a filter or one short action in one line. A long settings page is split into sections with a heading and a sentence on the left. The buttons are under the content in every layout (FORM-01).",
            RuleLevel.Should, Design, Check: "Test (CSS contract)"),
        new("FORM-15", "FORM", "Pickers",
            "A value that the native control cannot show well is chosen in a picker: an option with a picture and a description, a date or a period, a time or a time range, a colour, an appointment (a day and a time, FORM-18). The picker is a button that looks like a field and shows the value in the language of the page; the panel opens under it and, on a phone, fills the screen with an X at the top right like every dialog. The field posts one value in a fixed format (2026-10-10, 2026-10-10..2026-10-14, 09:30, 09:00..17:30, #b4235f, 2026-10-14T09:30), whatever the language. Everything can be done with the keyboard, and a picker that can be typed (time, colour) accepts typing. A native control stays the choice when it is enough. Tags are the one picker that is a field of its own: the user types, Enter or a comma makes a chip, an X or Backspace removes it, suggestions are a list under the field (also on a phone), and one value is posted, the tags joined by a comma. A dropdown with a list of checkboxes is the select picker with `data-multiple`; `data-select-all` adds a first row, Select all, with a box that is empty, ticked or in between and acts on the entries that are shown.",
            RuleLevel.Should, MatCms, Do: "<div class=\"mat-picker\" data-picker=\"date\"><input class=\"mat-picker__input\" id=\"due\" name=\"due\" value=\"2026-10-10\"></div>", Dont: "a text field where the user types a date in a format nobody told them", Check: "Test (script and CSS contract of the pickers) and browser"),
        new("FORM-16", "FORM", "Create what is missing",
            "Where a choice is made from a list the user also keeps (a tag, a correspondent, a project), the picker may offer to create what is missing: for a text that is not the name of an option the first row of the list is `Create \"text\"`, which creates it and chooses it in one step. Only where creating is cheap and reversible and needs nothing but a name; anything that needs more than a name (a second field, a decision, a confirmation) is a page of its own (LIST-01). The picker sends the name and takes the key back, keeps the panel open and says at the field why it did not work, announces what was created, and never creates anything by itself. What an app guesses for the field is offered as suggestions above the whole list, while nothing is chosen and nothing is searched, and the closed field counts them; a suggestion is never chosen for the user (FORM-15).",
            RuleLevel.Should, MatPaper, Why: "A list that has to be left to add one more tag is a list nobody keeps tidy; creating in the field, where the missing name was noticed, is the cheap way.", Do: "<div class=\"mat-picker\" data-picker=\"select\" data-create-url=\"/QuickCreate?kind=tag\" data-suggest-url=\"/Suggest?doc=5\">", Dont: "a create row for something that needs a second field, creating without the user choosing the row, a suggestion that is chosen unasked", Check: "Test (script contract) and browser"),
        new("FORM-17", "FORM", "Slider and range slider",
            "A value on a scale whose exact number does not matter is a slider, and a from and to on one scale is a range slider: native range inputs (one, or two named from and to) in a wrapper, so a form posts them, the browser's keyboard and role apply and they work without the script. The script draws one track with the filled part, a thumb for each input and a bubble with the value in its unit while the thumb is dragged or has the focus (or always), the minimum and the maximum at the ends and, where it helps, marks. A press on the track moves the nearest thumb; the thumbs of a range slider cannot cross and keep a least distance where one is set. The thumb is a target of 44 px (36 px for a small slider, MOBILE-04). The arrow keys move by one step, Page Up and Page Down by a tenth of the scale, Home and End to the ends, and each input has a name of its own for a screen reader (\"Price from\", \"Price to\") and says its value with its unit (A11Y-02). The value is always written out as text as well, because a slider alone does not say what it is set to (FORM-12); for an exact number the field is a number field.",
            RuleLevel.Should, Design, Why: "A slider is quick to set and hard to set exactly: a price range, a volume and the hours of a day are what it is good for, and a native input underneath keeps the keyboard, the form and the screen reader that a drawn control would have to rebuild.", Do: "<div class=\"mat-slider mat-slider--range\" data-slider data-min-gap=\"10\" data-format=\"{0} €\"><input class=\"mat-slider__input\" type=\"range\" id=\"from\" name=\"from\" value=\"20\"><input class=\"mat-slider__input\" type=\"range\" id=\"to\" name=\"to\" value=\"80\"></div>", Dont: "a slider that does not say its value, two sliders for a range that can cross, a thumb smaller than 44 px, a slider for an exact number", Check: "Test (markup contract, script, CSS) and browser"),
        new("FORM-18", "FORM", "Calendar and appointment picker",
            "A calendar that is always shown (`mat-calendar`) chooses one day, a period or several days and posts them in the formats of FORM-15 (2026-10-10, 2026-10-10..2026-10-14, 2026-10-10,2026-10-12). It can limit the days (`data-min=\"today\"`: nobody can pick the past), close days and weekdays, mark days with events and list the events of the chosen day, and it is a grid that the arrow keys walk, with touch targets of 44 px on a phone. An appointment is booked with the appointment picker (`data-picker=\"slot\"`): a month in which only the days with a free time can be chosen and carry a dot, then the times of the chosen day; a taken time or day is dimmed and says so in words, or is left out, never only coloured differently. It posts one value, 2026-10-14T09:30 (with the length of the appointment 2026-10-14T09:30..09:45), never offers a time that has passed or that starts before the minimum notice, and has a shortcut to the next free appointment. Where the availability comes from a server, the page answers the event `mat:slots-needed` per month and the picker shows that it is loading.",
            RuleLevel.Should, Design,
            Why: "People book a visit by looking for a free day first and a time second; a picker that lets them choose a day and then tells them that nothing is free wastes their time, and a taken time that is only grey looks like a design choice, not a fact.",
            Do: "<div class=\"mat-picker\" data-picker=\"slot\" data-min=\"today\" data-duration=\"15\"><input class=\"mat-picker__input\" id=\"visit\" name=\"visit\"></div>",
            Dont: "a date field and a time field for a booking, a calendar in which the past can be chosen, a taken time that is only a lighter grey",
            Check: "Test (script and CSS contract) and browser"),
        new("FORM-19", "FORM", "Code input",
            "A short code that is read from somewhere else (a one-time code from an authenticator app or an SMS, a PIN, a recovery code, a key) is a code input, not a plain text field: one box per character (`mat-otp`, 3 to 12 boxes) that takes only the characters that are allowed (digits by default, or letters, hex, a class such as `[A-Z2-7]`) and says when it refuses one. Typing fills a box and moves on, Backspace clears and goes back, a pasted code (with spaces or a dash) is spread over the boxes, and an SMS code is offered on the first box (`autocomplete=\"one-time-code\"`). It posts one value from a real input, so `required`, `pattern` and the messages of the form (FORM-03, FORM-05) work, and without the script it is a text field. A PIN is shown as dots. The form is sent when the code is complete only if the author asks for it (`data-submit`); an app that rejects a code clears the boxes, marks the field with a message at the field (A11Y-04) and focuses the first box. The boxes are one Tab stop with the arrow keys inside (A11Y-02), named by their place (\"Digit 3 of 6\"), 44 px high on a touch screen and never wider than the screen (MOBILE-04).",
            RuleLevel.Should, Design, Why: "Six separate fields that the user has to click through are slow and break pasting and SMS autofill; one long text field hides how many characters are missing. Sending the form the moment the code is complete saves a click, but a wrong code can cost an attempt, so it is the author's decision and off by default.", Do: "<div class=\"mat-otp\" data-otp data-length=\"6\" data-chars=\"digits\" data-submit><input class=\"mat-otp__input\" id=\"code\" name=\"code\" autocomplete=\"one-time-code\" required></div>", Dont: "six inputs with their own names that the user must tab through, a code field that does not take a pasted code, a PIN that is shown in clear", Check: "Test (script, CSS contract) and browser"),
        new("FORM-20", "FORM", "Number stepper",
            "A number that people change by a step or two (a quantity, a number of seats, a timeout) is a number stepper: a native number field with a button for less and one for more (`mat-stepper`), not the tiny spinners of the browser and not a text field. A press changes the value by the step, holding the button repeats and gets faster, Shift moves by ten steps, and the arrow keys and Page up and Page down do the same in the field. The value stays inside `min` and `max` and on the grid of the step, without rounding errors, and what is typed is put in order when the field is left. A button that cannot go further is dimmed with `aria-disabled`, never `disabled`, so that the focus stays; the buttons are named in the language of the page and the unit is shown as a suffix (`data-unit`). The buttons are as large as any control on a touch screen (BUTTON-05, MOBILE-04). Where the steps are many and the exact number matters (a port, a year), a plain number field is the better control (FORM-12).",
            RuleLevel.Should, Design, Do: "<div class=\"mat-stepper\" data-stepper><input class=\"mat-input\" type=\"number\" id=\"qty\" name=\"qty\" min=\"1\" max=\"10\" step=\"1\" value=\"3\"></div>", Dont: "two buttons that the page draws and wires itself next to a text field, or a number that can only be typed", Check: "Test (script) and browser"),
        new("FORM-21", "FORM", "File upload",
            "Files that the user sends are chosen in a file upload (`mat-upload`), not in the bare file field of the browser: a drop zone around a real file input, so that files can be dragged onto it or chosen with a click, Enter or Space (the zone is one Tab stop; on a touch screen it says \"Tap to choose\"). The files that were chosen are listed under it with name, size and a remove button named by the file (an image gets a thumbnail), and the form posts exactly what the list shows. `accept`, `data-max-size` and `data-max-files` are checked as the files arrive; a file that is refused is named with the reason in words at the field (A11Y-04), never by a colour alone, and the other files are still added. The limits are written in the zone before anybody chooses. `required`, `multiple` and the messages of the form (FORM-03, FORM-05) work as for any field, and without the script it is the native file field. Pasting an image is on only with `data-paste`. An app that uploads by itself draws progress and failures with `MatUi.upload`. Targets are 44 px on a touch screen and nothing is wider than the screen (MOBILE-04). The server checks the limits again.",
            RuleLevel.Should, Design,
            Why: "A bare file field is a small button and a file name, it says nothing about what it takes until it refuses, and it cannot show what will be sent. A drop zone with a list and the limits in plain sight answers all three, and a real input underneath keeps the form, the validation and the keyboard that a drawn control would have to rebuild.",
            Do: "<div class=\"mat-upload\" data-upload data-max-files=\"5\" data-max-size=\"10MB\"><input class=\"mat-upload__input\" type=\"file\" id=\"docs\" name=\"docs\" multiple accept=\".pdf,image/*\"></div>",
            Dont: "a drop zone that the page draws and wires itself, a file field that takes anything and does not say what it takes, a refusal that is only a red border, a list that shows files the form will not send",
            Check: "Test (markup contract, script, CSS) and browser"),
        new("FORM-22", "FORM", "Rating",
            "A value that people give on a short scale (a review, a priority, how likely they are to recommend) is a rating: a fieldset with a legend and a native radio button for each value (`mat-rating`, three to ten), drawn as stars, hearts or dots, so a form posts it, the keys and the screen reader work and, without the script, it is a row of radio buttons. The pointer shows the value it is on, a click chooses it and, with `data-clearable`, a click on the chosen value clears it; half steps are twice the radios, and the value 0 is \"no rating\". An average that is only shown is a read-only rating (`mat-rating--readonly`, `data-value`): it may be filled in part, is one image with its value in words (\"Rated 4.5 out of 5\", A11Y-03) and has the number beside it (`data-show-value`), because shapes alone do not say it (COLOR-04, FORM-12). A chosen shape is filled and an empty one is an outline. The shapes are 44 px targets (36 px for a small rating) and shrink on a phone rather than overflow (MOBILE-04). A change is told by `mat:rating-change`. For a wide scale or an exact number use a slider or a number field (FORM-17, FORM-20).",
            RuleLevel.Should, Design, Do: "<fieldset class=\"mat-field mat-fieldset mat-rating\" data-rating><legend class=\"mat-legend\">Overall</legend><input class=\"mat-rating__input\" type=\"radio\" id=\"q-1\" name=\"q\" value=\"1\"><label class=\"mat-rating__label\" for=\"q-1\">1 star</label> ... </fieldset>", Dont: "five buttons or icons that the page wires itself, a rating that is only coloured, or an average drawn as a picture without its number", Check: "Test (script and CSS) and browser"),
        new("FORM-24", "FORM", "A form is checked when it is sent",
            "A form is checked when it is sent, not while the user types for the first time. Every field that is wrong gets its message at the field and in the summary at the top, the first of them gets the focus, and an error goes away as soon as its field is right again, so that a person who fixes a field sees that it is fixed. A form that comes back from the server with errors is drawn the same way (`is-invalid`, `aria-invalid`, the summary), so that the browser and the server say the same thing, and what only the server can know (a name that is taken) comes back the same way. A submit button with `formnovalidate` skips the check (FORM-05).",
            RuleLevel.Should, Design,
            Why: "A message while someone is still typing is noise, and a message that stays after the field was fixed is wrong. Checking on send, clearing on fix and moving the focus to the first error keeps both short.",
            Do: "<form class=\"mat-form\" novalidate> <div data-validation-summary hidden>...</div> <div class=\"mat-field is-invalid\"> ... <span class=\"mat-error\" aria-live=\"polite\">Please fill in this field.</span> </div> </form>",
            Dont: "a message on every key stroke of a field the user has not left yet, an error that stays after the field is right, a server that draws its errors in another way than the script does",
            Check: "Test (script) and browser"),

        // ------------------------------------------------------------------------------------------------- BUTTON
        new("BUTTON-01", "BUTTON", "Four kinds",
            "There are four kinds of button: primary, secondary, ghost and danger. Nothing else: no bare `<button>`, no framework classes, no fifth style.",
            RuleLevel.Must, MatmonCloud, Check: "Test (markup contract: every button of an example has a type and only classes that exist) and review"),
        new("BUTTON-02", "BUTTON", "One primary",
            "A view has one primary button: the thing most people came to do. Everything else is secondary or ghost.",
            RuleLevel.Should, Design),
        new("BUTTON-03", "BUTTON", "Labels start with a verb",
            "Button text starts with a verb and names the result: Save, Open, Verify connection. Not OK, not Submit.",
            RuleLevel.Should, Matthix),
        new("BUTTON-04", "BUTTON", "Icons",
            "Where an icon helps, it comes before the label. A button that is only an icon has an `aria-label` and a tooltip.",
            RuleLevel.Should, Owner),
        new("BUTTON-05", "BUTTON", "Size of the target",
            "Buttons and inputs are 40 px high with a mouse and 44 px on a touch screen; compact controls are 32 px with a mouse and 36 px on a touch screen. Nothing else that a finger has to hit is smaller than 44 px, and what counts is the area that takes the tap (MOBILE-04).",
            RuleLevel.Must, Matthix, Check: "Test (tokens)"),
        new("BUTTON-06", "BUTTON", "Links and buttons",
            "A button does something, a link goes somewhere. A link that looks like a button (`<a class=\"mat-btn\">`) is fine for navigation; a link never submits.",
            RuleLevel.Should, Design),

        // ------------------------------------------------------------------------------------------------- DIALOG
        new("DIALOG-01", "DIALOG", "Everything is a dialog",
            "Confirmations, notices and inputs are always shown as a dialog of the toolkit: `MatUi.confirm`, `MatUi.alert`, `MatUi.prompt`, or `data-confirm` on a button, link or form. `window.confirm`, `alert` and `prompt` are never used.",
            RuleLevel.Must, Owner, Do: "<button data-confirm=\"Delete this backup?\">", Dont: "onsubmit=\"return confirm(...)\"", Check: "Test (script contract)"),
        new("DIALOG-02", "DIALOG", "The tools of a list are dialogs",
            "Search, filter and sort of a list open dialogs (LIST-03). Their buttons stand under the fields: Apply, Cancel, then a gap and Reset.",
            RuleLevel.Must, Owner),
        new("DIALOG-03", "DIALOG", "On a phone every dialog is full screen",
            "Below 640 px every dialog fills the screen. The close button (X) is at the top right of the head. The dialog respects the safe areas of the device.",
            RuleLevel.Must, Owner, Check: "Test (CSS contract)"),
        new("DIALOG-04", "DIALOG", "Structure",
            "A dialog has a head (title and X), a body that scrolls on its own, and a foot with the buttons under the content, positive to negative.",
            RuleLevel.Must, Owner),
        new("DIALOG-05", "DIALOG", "Behaviour",
            "Escape closes a dialog, a click outside closes one that is not a data-entry form, focus moves into the dialog when it opens and back to the opener when it closes, and the page behind does not scroll.",
            RuleLevel.Must, Design, Check: "Test (script) and browser"),
        new("DIALOG-06", "DIALOG", "Destructive confirmation",
            "When the confirmation is for something destructive, Cancel comes first and the destructive action is the last button, in the solid danger style. Otherwise the confirming button comes first.",
            RuleLevel.Must, Owner, Check: "Test (browser: Cancel first, a gap, the danger button last)"),
        new("DIALOG-07", "DIALOG", "Menus and dropdowns on a phone",
            "A custom dropdown or selection list that would not fit on a small screen becomes a full-screen sheet there, like a dialog. A context menu with a few items stays a small popover.",
            RuleLevel.Should, MatMail),

        // -------------------------------------------------------------------------------------------------- TABLE
        new("TABLE-01", "TABLE", "Numbers and technical values",
            "Numbers are right-aligned with tabular figures. IDs, IP addresses, versions, ports and timestamps use the mono font.",
            RuleLevel.Should, Matthix),
        new("TABLE-02", "TABLE", "Every cell has a label",
            "Every `<td>` has `data-label` with the name of its column. Below 720 px a row becomes a card and the label is drawn in front of the value.",
            RuleLevel.Must, MatSplit, Check: "Test (CSS contract)"),
        new("TABLE-03", "TABLE", "Status is a pill with text",
            "A state is shown as a pill with a dot and a word (Online, Warning, Offline, Unknown). Colour alone never carries the information.",
            RuleLevel.Must, Matthix),
        new("TABLE-04", "TABLE", "Wide tables",
            "A table that cannot become cards scrolls horizontally inside its own container and shows that it does.",
            RuleLevel.Should, Matthix),
        new("TABLE-05", "TABLE", "Selecting rows",
            "A table, a gallery or a list of cards that acts on several items at once has a check in every item (`data-select-row`) and, where it helps, one that selects all the items of this page (`data-select-all`). Each check is named by what it selects, by an `aria-label` (`\"Select Documents\"`) or by the label that wraps the row of a list, so that a screen reader says which item. The item of a ticked check is a tint behind the whole item (COLOR-08), never a bar at one side. While something is selected a bar shows how many (`data-bulk-bar`, `data-bulk-count`); when there are more pages it says that it counts this page (\"7 selected on this page\"), and the action works on what is selected and on nothing that is not shown.",
            RuleLevel.Should, Design,
            Why: "A check per row is how people choose several things. The name and the tint say which, and the count says how far an action reaches, which keeps \"delete\" from reaching more than was on the screen.",
            Do: "<input type=\"checkbox\" data-select-row aria-label=\"Select Documents\">",
            Dont: "a check without a name, a selected row that is only a bar at its side, a bulk action that reaches pages that are not shown without saying so",
            Check: "Test (script: the item of a ticked check is marked) and browser"),


        // -------------------------------------------------------------------------------------------------- COLOR
        new("COLOR-01", "COLOR", "Tokens only",
            "Colours come from the tokens (`var(--mat-...)`), never as a literal in an app's CSS. A hard-coded white or grey is a bug that shows up as a bright block in dark mode.",
            RuleLevel.Must, MatCms, Check: "Test (toolkit CSS)"),
        new("COLOR-02", "COLOR", "Light and dark",
            "Every app works in light and dark, and follows the system by default. The dark set exists for every colour token; the two places it is written (explicit `data-theme=\"dark\"` and system) are identical.",
            RuleLevel.Must, Owner, Check: "Test"),
        new("COLOR-03", "COLOR", "Status colours have a meaning",
            "Green is success and healthy, amber is attention, red is an error or a destructive action, blue is information. The accent is never used for one of these meanings.",
            RuleLevel.Must, Matthix),
        new("COLOR-04", "COLOR", "Colour is never the only information",
            "Anything that colour tells (state, importance, selection) is also told by text or an icon.",
            RuleLevel.Must, Matthix),
        new("COLOR-05", "COLOR", "Contrast",
            "Text reaches WCAG AA: 4.5:1 for body text, 3:1 for large text and for the borders of controls. Muted text still passes; faint text is only for placeholders and disabled states.",
            RuleLevel.Must, Matthix, Check: "Test"),
        new("COLOR-06", "COLOR", "Flat surfaces",
            "Surfaces are plain colours, and so are the logo tile and the avatar (the flat accent). No gradient backgrounds, no glow around a button or a logo, no blur behind a bar or a dialog. A gradient is only for data, such as the colour ramps of the colour picker.",
            RuleLevel.Should, Design, Check: "Test (toolkit CSS: no radial gradient, no blur, no brand gradient token) and review"),
        new("COLOR-07", "COLOR", "Previews stay as they are",
            "Content that shows something from outside (an e-mail body, a document preview, a QR code) stays white in dark mode on purpose.",
            RuleLevel.Should, MatCms),
        new("COLOR-08", "COLOR", "Selected is a tint, not a bar on one side",
            "What is selected or current (a menu item, an entry of the index, a tab, a row) is shown by a tint of the accent behind the whole item, a stronger weight and the accent on its icon. Never by a coloured bar or border on one side of a rounded item: it looks generated and it breaks at the corners. A line under tabs is the one exception, because it is the underline of the tab row, and then the tab has square corners.",
            RuleLevel.Should, Design, Why: "A bar at one edge of a rounded shape has no clean corner and is what every generated interface does.", Do: ".mat-nav__item[aria-current=\"page\"] { background: var(--mat-accent-soft-strong); }", Dont: "border-left: 3px solid var(--mat-accent) on a rounded item, an inset shadow at one side, a ::before bar", Check: "Test (toolkit CSS)"),
        new("COLOR-09", "COLOR", "Schemes change surfaces, never the accent",
            "An app may offer colour schemes besides the standard look, and then they are these: `paper` (warm, slightly yellowed surfaces), `contrast` (pure white or pure black, strong lines instead of shadows, the borders of controls at 3:1 or more) and `oled` (a black page and menu, near-black surfaces; dark mode only, in light mode it is the standard look). A scheme is `data-scheme` on `<html>`, next to `data-theme`, `data-app` and `data-accent`; absent, `standard` or any other value is the standard look. A scheme changes surfaces only: the backgrounds, the lines, the text, the status texts where AA needs it, the shadows, the dim layer and the scrollbar. It never sets an accent token, so every combination of scheme, mode, accent and app works and reaches AA (COLOR-05); where its surfaces need darker links it lowers `--mat-accent-text-keep`, the share of the accent that a link keeps. Its dark values are written twice, like the dark set (COLOR-02). The choice belongs to the user and is kept with the account (`data-scheme-set`, `data-scheme-save-url`), or in the browser.",
            RuleLevel.Should, Owner, Why: "MatPaper had a paper, a high-contrast and a black scheme before it moved onto the toolkit: reading in daylight, needing strong contrast and using an OLED screen ask for other surfaces, and none of them may cost an app its own colour. Decided by the owner on 2026-10-12.",
            Do: "<html data-app=\"matpaper\" data-theme=\"dark\" data-scheme=\"oled\">", Dont: "a scheme that sets --mat-accent, a second dark mode of the app's own, a scheme the user cannot leave", Check: "Test (toolkit CSS, contrast of every scheme, mode and accent)"),
        new("COLOR-10", "COLOR", "A colour chosen by the user is data",
            "A colour that a user chooses for a thing (a tag, a project, a folder) is data, not a part of the design. It is shown as a mark next to the name: a dot (`mat-dot`), a tag with a dot before its text (`mat-tag`), an icon in that colour (`mat-icon`) or the dot of an option in a picker. It is set with `data-colour=\"#rrggbb\"` (`#rgb` works too) and the script puts it into `--mat-swatch`: never with an inline style, never as a literal colour in a stylesheet. It is never the only signal (COLOR-04): the name stands next to it. And the colour of the text is never derived from it: any colour a user can choose is safe, because the text stays in the muted text colour that reaches AA (COLOR-05) and the colour is only the dot. Anything that is not a hex colour is ignored, and the mark looks neutral.",
            RuleLevel.Should, MatPaper, Why: "Users pick colours for their tags and projects, and some of them pick white, black or something that no text colour reads well on; a dot cannot fail AA, text on a user's colour can.",
            Do: "<span class=\"mat-tag\" data-colour=\"#d6336c\">Invoices</span>", Dont: "style=\"background: #d6336c\", a tag whose text colour is worked out from the user's colour, a colour with no name beside it", Check: "Test (markup contract, toolkit CSS, script) and browser"),
        new("COLOR-11", "COLOR", "A brand changes tokens only, within limits, and is checked",
            "A company's brand is a set of values for documented tokens, never CSS of its own. The Studio offers the tokens of `matui.tokens.css` that are look (colours, radii, spacing, sizes, fonts, line heights, motion), not the derived or structural ones (the accent family, layers, safe areas, shadows). Every value has the type of its token (a colour, a length, a number, a duration, a font stack ending in a generic family, from a safe set of characters) and stays within limits that protect usability: touch targets of 44 px (36 px compact, MOBILE-04), a body text of 14 px or more, a line height of 1.2 to 2, radii of 0 to 24 px, a type scale that only grows. Light and dark values are separate. A brand is written after the tokens in `matui.css`, the dark set twice and identical (COLOR-02); one that sets nothing writes nothing. Before it is saved or released the contrast checks (COLOR-05) run on its surfaces, in light, in dark and in every scheme (COLOR-09), with the accent of every app: a failing pairing is an error that blocks, advice stays advice. It may also change what a scheme itself sets, inside that scheme; an app sets shape, spacing, type and motion, never surfaces.",
            RuleLevel.Must, Owner, Why: "Any company can build its own branding with MatDesign (docs/PRODUCT.md). Free CSS would let a brand break the interface it brands; tokens with types and limits, checked for AA before they are saved, keep every brand usable. Decided by the owner on 2026-10-14.",
            Do: ":root { --mat-radius: 8px; --mat-fs-md: 1rem; }", Dont: "a brand that sets a selector, a url, an import or a token outside its limits, a surface and a text colour under 4.5:1, a control under 44 px on a touch screen", Check: "Test (validator, overlay, checks) and browser"),

        // --------------------------------------------------------------------------------------------------- TYPE
        new("TYPE-01", "TYPE", "System fonts",
            "Apps use the system font stack and the system mono stack. No web fonts from another site: apps must work offline and as a PWA. The toolkit itself ships no font file; the only exception is the font files of a company's own brand (IDENT-08), which lie in its own volume and its releases, are copied with the app and are declared with `font-display: swap`.",
            RuleLevel.Must, MatSplit, Check: "Test (toolkit CSS)"),
        new("TYPE-02", "TYPE", "The scale",
            "Type sizes come from the scale (12, 13, 15, 17, 20, 26, 34 px). Body text is 15 px, table text 13 px, the page title 26 px.",
            RuleLevel.Should, Design),
        new("TYPE-03", "TYPE", "Mono for technical values",
            "IDs, versions, hashes, ports, paths and code are set in mono. Labels and technical values in the same row are not mixed in one font.",
            RuleLevel.Should, Matthix),
        new("TYPE-04", "TYPE", "Line length",
            "Running text is at most about 70 characters wide.",
            RuleLevel.Should, Matthix),

        // --------------------------------------------------------------------------------------------------- SPACE
        new("SPACE-01", "SPACE", "The 4 px scale",
            "Gaps and paddings come from the scale (4, 8, 12, 16, 20, 24, 32, 40, 48 px).",
            RuleLevel.Should, Design),
        new("SPACE-02", "SPACE", "Radii",
            "Cards and dialogs use the large radius (8 px), buttons, inputs and menu items 6 px, small marks 3 or 4 px. Only badges, status pills and switches are round. Do not invent a radius.",
            RuleLevel.Should, Matthix, Check: "Test (toolkit CSS: the radii are small and only pills are round)"),
        new("SPACE-03", "SPACE", "Elevation",
            "A card is a surface with a line and hardly a shadow; popovers carry the middle shadow, dialogs the large one. Lines and surfaces structure more than shadows do, and nothing lifts on hover.",
            RuleLevel.Should, Matthix, Check: "Test (toolkit CSS: nothing lifts on hover) and review"),
        new("SPACE-04", "SPACE", "Motion",
            "Motion is short and has a purpose: 120 ms for hover and press, 180 ms for menus and tabs, 280 ms for dialogs and the drawer, one easing curve. With `prefers-reduced-motion` everything that is not needed stops.",
            RuleLevel.Must, Matthix, Check: "Test (toolkit CSS)"),
        new("SPACE-05", "SPACE", "Scrollbars appear while scrolling",
            "Scrollbars are invisible until something scrolls and fade out about a second after. On a touch screen the system's overlay scrollbars apply.",
            RuleLevel.Must, Owner, Check: "Test (script)"),
        new("SPACE-06", "SPACE", "Component shape is changed through documented properties",
            "The shape of a control (its radius, padding, height, border width, gap, type size and weight) is changed through the documented `--mat-<component>-*` properties and through the global tokens, never by overriding the classes of the toolkit. A property is set on `:root` for every app, on `[data-app]` for one app or on one element, to a value of its type (a length, a number, a duration, a token for a colour or a font), and an app that sets none sees no change: every use in the toolkit is `var(--mat-btn-radius, var(--mat-radius))`, so the fallback is the default and the property has no value of its own. A height is a floor that a touch screen keeps at 44 px or more (MOBILE-04): a value under 44 px (never under 32) is written for `(pointer: fine)` only. Limits: radius 0 to 24 px, padding 0 to 48, border 0 to 4, dialog or toast 200 to 960. Values win in the order toolkit, brand, app (`[data-app]`), scheme the user chose. No property gives a control a colour of its own (COLOR-01) or a shadow (SPACE-03). The properties are written in the CSS, one `@prop` line above the rule that uses them, and the pages of the components and the tokens page list them from there.",
            RuleLevel.Should, Design, Why: "A brand that overrides classes copies the toolkit's selectors and breaks with its next version; a documented property is a promise that survives it and that an editor can offer with a type and limits.", Do: ":root { --mat-btn-radius: 0; } /* every button square */", Dont: ".mat-btn { border-radius: 0; } /* a class overridden in the app */", Check: "Test (component properties)"),

        // ---------------------------------------------------------------------------------------------------- ICON
        new("ICON-01", "ICON", "One sprite, inline",
            "Icons are inline SVG from the toolkit sprite: 24 px grid, 2 px stroke, round caps, `currentColor`. No icon font, no icon CDN, no image icons, no emoji in the interface.",
            RuleLevel.Must, MatSplit, Why: "Works offline, follows the theme and the text size.", Check: "Test (sprite)"),
        new("ICON-02", "ICON", "Same meaning, same icon",
            "A meaning has one icon everywhere: save, edit, trash, search, filter, sort, back, settings, user ... (see the icon list). Icons are used where they help, not on everything.",
            RuleLevel.Must, Owner),
        new("ICON-03", "ICON", "Icon only with a name",
            "An icon without a visible label has an accessible name (`aria-label`) and, on a pointer device, a tooltip.",
            RuleLevel.Must, Design, Check: "Test (every icon-only button of an example has a name) and review"),
        new("ICON-04", "ICON", "App logos",
            "Every app has a logo for the menu (a tile with a glyph, IDENT-03), a favicon (SVG) and the PWA icons (192, 512 and a maskable 512).",
            RuleLevel.Should, Design),
        new("ICON-05", "ICON", "More icons are optional",
            "The sprite of the toolkit stays small: the icons the apps use. An app that needs more takes them from the icon library, which is made of files of its own (`matui-iconlib.svg`, `iconlib.json` and each icon as a single .svg), sorted into categories where an icon can be in several. The library is not part of `matui.css` and nothing in the toolkit depends on it, so an app can do without it, and it never becomes part of the sprite as a whole. Its icons follow ICON-01 to ICON-03 like the others, and one that gets a meaning in the interface is moved into the sprite (ICON-02: one meaning, one icon).",
            RuleLevel.Should, Owner, Why: "A smart home needs two hundred icons and most apps twenty: an app takes what it needs and the toolkit stays small.", Check: "Test (library)"),

        // -------------------------------------------------------------------------------------------------- MOBILE
        new("MOBILE-01", "MOBILE", "Phones are first-class",
            "Every page is designed and checked at 390 px wide, not only at desktop width. Nothing scrolls sideways.",
            RuleLevel.Must, Owner),
        new("MOBILE-02", "MOBILE", "What changes below 900 px",
            "The menu becomes a drawer behind a burger button in the top bar; the breadcrumb shows its last two items; two- and three-column grids become one column; secondary table columns can be hidden (`mat-hide-sm`).",
            RuleLevel.Must, Design),
        new("MOBILE-03", "MOBILE", "Dialogs and tables",
            "Dialogs are full screen (DIALOG-03), tables become cards (TABLE-02).",
            RuleLevel.Must, Owner),
        new("MOBILE-04", "MOBILE", "Touch",
            "Targets are at least 44 px (36 px for compact controls), there is no information that only a hover shows, and the safe areas of notches and home indicators are respected. What is 44 px is the hit area, the part of the screen that takes the tap, not the drawn mark: a check, a switch, the X of a chip or a dot sits in a label, a padding or an area of 44 px around it, which moves nothing and does not depend on the size of the mark. A row of shapes that has no room for them at that size (a rating of ten on a phone) goes on a second row, and a month of days that has to fit a narrow box and a code of many boxes (FORM-19) are only narrower, never lower. A link inside a sentence is exempt.",
            RuleLevel.Must, Matthix, Check: "Test (touch rules of the CSS and of each control) and browser (touch-audit.js)"),
        new("MOBILE-05", "MOBILE", "Installable",
            "An app that people use daily is a PWA: manifest, `theme-color`, icons and a service worker that caches the shell.",
            RuleLevel.May, MatMail),

        // --------------------------------------------------------------------------------------------------- A11Y
        new("A11Y-01", "A11Y", "Focus",
            "Every interactive element shows a visible focus ring from the accent. Focus is never removed without a replacement. The first focusable element is the skip link.",
            RuleLevel.Must, Matthix, Check: "Test (the skip link is the first thing on every page of this site, no ring is taken away without another one) and browser"),
        new("A11Y-02", "A11Y", "Keyboard",
            "Everything can be done with the keyboard: menus (arrow keys), tabs (arrow keys, Home, End), dialogs (Escape, focus trap), pickers and other panels (Escape closes them and gives the focus back), and the search with `/`, which opens the search dialog or puts the cursor in the search field.",
            RuleLevel.Must, Design),
        new("A11Y-03", "A11Y", "Landmarks and names",
            "A page has `nav` for the menu (labelled), `main` for the content, `nav aria-label=\"Breadcrumb\"` for the breadcrumb and, where it has one, `footer` after the content; it has exactly one `h1`. Controls have labels; an image that carries information has an `alt` that says it and a decorative one has `alt=\"\"`; the current page is `aria-current=\"page\"`.",
            RuleLevel.Must, Matthix, Check: "Test (every page of this site has one h1, main, a breadcrumb and images with alt) and the markup contract of the examples"),
        new("A11Y-04", "A11Y", "Errors are announced",
            "A form error is written next to the field, linked with `aria-invalid`, and summarised at the top.",
            RuleLevel.Should, Matthix),
        new("A11Y-05", "A11Y", "Reduced motion",
            "With `prefers-reduced-motion` animations and transitions are reduced to nothing (SPACE-04). The one exception is a spinner, which turns slowly instead of stopping: a spinner that does not move says nothing is happening.",
            RuleLevel.Must, Matthix, Check: "Test (toolkit CSS)"),
        new("A11Y-06", "A11Y", "The page names its language",
            "`<html lang>` names the language of the page, `en` or `de`, on every page, the error and the sign-in page included. The script writes its own texts in that language (a page in another language changes them, CODE-11), and the pickers and the schedule write dates in it (`data-locale` changes only the dates). A passage in another language inside the page has its own `lang`. Without `lang` the script writes English.",
            RuleLevel.Should, Design,
            Why: "A screen reader chooses its voice and its pronunciation from `lang`, a browser decides about translation and hyphenation from it, and the script chooses the language of every text it writes from it.",
            Do: "<html lang=\"de\" data-app=\"matmail\">",
            Dont: "a page without lang, lang=\"en\" on a page in German, a French quotation in a German page without its own lang",
            Check: "Test (every page of this site has lang, the script reads it) and review"),
        new("A11Y-07", "A11Y", "State is told by the attribute that names it",
            "What a control is doing is told by the ARIA attribute that names it, and the attribute is kept true: `aria-expanded` on what opens (a parent in the menu, the heading of a group, a tree item, the button that opens a menu), `aria-pressed` on a button that toggles (a segment of a choice of views, the eye of a password field), `aria-selected` or `aria-checked` on what is chosen (`mixed` for in between), `aria-current` on the current page (A11Y-03), `aria-invalid` on a field that is wrong (A11Y-04), `aria-busy` on what is still loading (A11Y-10). A button that cannot go further and has the focus (the end of a carousel, the limit of a stepper, the first period of a schedule) is `aria-disabled`, never `disabled`: a disabled button drops the focus and tells nothing.",
            RuleLevel.Should, Design,
            Why: "A class is only a picture; a screen reader reads the attribute. Where the CSS reads the attribute too (the tree has no open class), the picture and what is said cannot differ.",
            Do: "<button class=\"mat-nav__item mat-nav__parent\" aria-expanded=\"false\" aria-controls=\"sub-items\">",
            Dont: "a class that only the CSS knows (is-open) and no attribute, a disabled button that held the focus, aria-pressed on a button that opens a menu (that is aria-expanded)",
            Check: "Test (markup contract and script of each control) and review"),
        new("A11Y-08", "A11Y", "A change that does not move the focus is told in a live region",
            "What changes on the page without the focus moving is told to a screen reader in a live region: a toast is `role=\"status\"` and polite, the count that follows a filter or a search (\"12 of 130 rules\"), the number of matches of a tree filter, the page of a carousel or a schedule, a file that was added or refused, a thing that was created in a picker. Polite is the default; a message that has to interrupt is rare and goes with the field it is about (A11Y-04). The region is never `hidden` or `display: none`, because a hidden live region is not read. A message is a sentence in words, not an icon or a colour (COLOR-04), and it does not repeat what the focus already says. A carousel that moves by itself says nothing, so that it does not talk over the user.",
            RuleLevel.Should, Design,
            Why: "A sighted user sees the list shrink or the toast appear; a user of a screen reader hears nothing unless the page says it.",
            Do: "<span class=\"mat-toolbar__info\" aria-live=\"polite\">12 of 130 rules</span>",
            Dont: "a toast that is not role=status, a live region with the hidden attribute, an announcement that is only an icon, a message read out on every page of a carousel that moves by itself",
            Check: "Review (the status of the upload, the toasts and the carousel are held by their tests)"),
        new("A11Y-09", "A11Y", "The focus is not lost",
            "When the element that has the focus goes away or changes, the focus moves to the nearest place that makes sense and never falls to the top of the page. A dialog gives it back to the button that opened it (DIALOG-05); a panel that closes with Escape gives it back to its field; removing a file moves it to the next remove button, or to the drop zone when none is left; a form that is sent with errors puts it on the first field that is wrong (FORM-24); a control that pages its content (a schedule, a carousel) keeps it, because its buttons are `aria-disabled` and not `disabled` (A11Y-07).",
            RuleLevel.Should, Design,
            Why: "Keyboard users and users of a screen reader find their place again by the focus. When it falls to the top of the page they start over.",
            Do: "after the last file is removed: the focus goes to the drop zone",
            Dont: "removing the element that has the focus and leaving the focus on the body, a Next button that is disabled at the end while it has the focus",
            Check: "Test (dialogs give the focus back, a form puts it on the first error) and browser (upload, schedule)"),
        new("A11Y-10", "A11Y", "What is loading says so, and so does what failed",
            "Something that takes time says so, in place and in words. A spinner always comes with a text (`role=\"status\"`); a bar that shows a task is `role=\"progressbar\"` with a name and a value; a region that is filling is `aria-busy=\"true\"` until it is done; a button that waits for the server is `is-loading` and `aria-busy` and cannot be pressed twice; content that has a shape (a list, a card) gets a skeleton, so that the page does not jump when it arrives. What finished is told in a live region (A11Y-08). What failed says so in words, where the content would have been, and offers to try again: a month of appointments that could not be loaded, the children of a tree item, a file that could not be sent. A failure is never an empty list, which would say that there is nothing.",
            RuleLevel.Should, Design,
            Why: "A page that shows nothing while it loads looks broken, and one that shows nothing after it failed looks like an empty result.",
            Do: "<div class=\"mat-loading\" role=\"status\"><span class=\"mat-spinner\"></span><span>Loading the backups ...</span></div>",
            Dont: "a spinner without a text, a list that stays empty when the request failed, a progress bar without a name, a page that jumps when the content arrives",
            Check: "Review (the spinner and the skeleton are examples with this markup; the failed states of the appointment picker, the tree and the upload are held by their tests)"),

        // --------------------------------------------------------------------------------------------------- CODE
        new("CODE-01", "CODE", "One code base per control",
            "Table, pagination, toolbar, form, field, tabs, dialog and button each have one implementation, shared by every page. Several equal controls may share a page (unique ids).",
            RuleLevel.Must, Owner),
        new("CODE-02", "CODE", "Nothing outside the toolkit",
            "A page is built only from the toolkit's classes. No inline styles, no inline scripts, no new class for something the toolkit already ships. An app's own classes carry the app's prefix.",
            RuleLevel.Must, MatmonCloud, Check: "Test (pages use only classes that exist, no inline style, handler or script)"),
        new("CODE-03", "CODE", "No outside resources",
            "No external fonts, icons, scripts or stylesheets: the app works offline and under a strict content security policy.",
            RuleLevel.Must, MatSplit, Check: "Test (toolkit)"),
        new("CODE-04", "CODE", "Names",
            "Toolkit classes start with `mat-`, custom properties with `--mat-`, data-attributes of behaviour are named after what they do (`data-confirm`, `data-show-if`). Block, element and modifier: `mat-card__head`, `mat-btn--primary`.",
            RuleLevel.Must, Design, Check: "Test (toolkit CSS)"),
        new("CODE-05", "CODE", "Language",
            "Code, identifiers and comments are English; the text of the interface is in the language of the app, with translated validation messages.",
            RuleLevel.Should, MatCms),
        new("CODE-06", "CODE", "Controls render nothing when there is nothing to show",
            "A pagination with one page, an empty alert, a toolbar without tools render no markup at all.",
            RuleLevel.Should, MatSplit),
        new("CODE-07", "CODE", "The documentation shows the code with the example",
            "Every example of the documentation (the components, the layout, the utilities and the styleguide of a release) shows its code with it, never behind a click: beside the example where the window is wide, below it otherwise, and below it for an example that needs the whole width (a table, a bar, a grid). The code is the markup that is drawn, from one source, coloured, with a Copy button; under the title the classes and the data attributes that the examples use are named.",
            RuleLevel.Should, Design, Why: "A developer copies what they see. Code that is one click away is not looked at, and code that is typed next to a picture drifts from it.", Do: "<div class=\"doc-example__body\"><div class=\"doc-example__live\">the example</div><div class=\"doc-code\">HTML | Copy, the code</div></div>", Dont: "a Markup disclosure, a screenshot instead of a live example, code that is written by hand next to the picture", Check: "Test (the page of the code is the code of the example) and browser"),
        new("CODE-08", "CODE", "A group of components is shown in a real page",
            "Beside its components the documentation shows each group in a real page of a sample app, opened when it is wanted: the controls are judged where they are used and not only on their own. The page can be a desktop window or a phone, can be opened by itself, and a component that the page uses can be outlined in it.",
            RuleLevel.Should, Design, Why: "A button that looks right alone can be wrong in a form; seeing the group in a page is how the spacing, the order and the neighbours are judged.", Do: "<details class=\"doc-context\"> a frame of /Preview with the marks of the components in it </details>", Dont: "a mock-up that is drawn by hand and can differ from the toolkit, a frame that loads before it is opened", Check: "Test (every mark finds its component in the page) and browser"),
        new("CODE-09", "CODE", "A company's release may carry its own prefix and name",
            "A release can rename the toolkit for a company: the class prefix of the source becomes the company's prefix (2 to 8 lower-case letters and digits, none that the browser or the toolkit uses, such as `data`, `aria`, `is` or `has`) and the product name becomes its own (letters only, a capital first). The rename is done by the build, on a copy of the files, on token boundaries (classes, ids, custom properties, `data-` attributes, events, storage keys, sprite ids, the global, the file names; `format-`, an address or another app's name is never touched), and the copy is held to the toolkit's own checks before it is published: no name of the source left, every class, property and icon that is used exists, the script is well formed. The source of the toolkit is never edited by hand for a brand.",
            RuleLevel.Must, Owner, Why: "Any company builds its own toolkit with MatDesign (docs/PRODUCT.md, stage 15). A copy that is renamed by hand drifts from the source and breaks without a message; a rename that is a function of the source and is checked cannot.", Do: "the Studio's white label setting, checked by a trial build, applied in the Build stage of the release pipeline", Dont: "a search and replace in the repository, a prefix that the browser reads as something else, a release whose renamed copy was not checked", Check: "Test (the renamer, the checks, the release) and browser"),
        new("CODE-10", "CODE", "Who may change what in the Studio is decided on the server, from a role",
            "A person of the Studio has exactly one role (administrator, editor or viewer), read from the people on every request, never from a cookie. Every page and every handler that changes something declares the capability it needs, and the server refuses a person who lacks it with a page that says which role would do (status 403) before the handler runs; a control that the person may not use is not drawn, or is turned off with the reason, but hiding a control is never the protection. The last active administrator cannot be deleted, disabled or demoted, nobody removes themselves or changes their own role, a password set by an administrator has to be changed at the next sign-in, and a password change or a disabled account ends the sessions of the person. A secret (a password, a hash, a salt) never enters the history, the activity list, a log or a page.",
            RuleLevel.Must, Design, Why: "One instance serves one company, and more than one person works in it (docs/PRODUCT.md, stage 16). A permission that only a hidden button enforces is no permission; a role in a cookie outlives the change that took it away; a history that holds a hash is a second place to lose it.", Do: "[RequireCapability(Capability.EditDesign)] on the handler, StudioRole.Can(role, capability) as the one decision, the id of the person in the cookie and the person read again on every request", Dont: "a check that only the page makes, a role copied into a cookie or a claim, an administrator that can remove the last administrator, a password in a log or in a revision", Check: "Test (every handler declares a capability, a crawl as each role, the guards, secrets never in the volume) and browser"),
        new("CODE-11", "CODE", "The texts the script writes can be changed",
            "The few texts that the script writes itself (the buttons and titles of the dialogs, the label of the theme button, the pickers, the messages of a form, and the texts of the controls that draw something: the upload, the schedule, the tree, the carousel, the rating, the code input, the list of rows, the stepper, the slider) are English or German, chosen by `lang` of the page (A11Y-06). Every key is in both languages, and an app changes any of them with a `data-<control>-<name>` attribute on `<html>` or on the element (`data-pk-apply`, `data-dlg-ok`, `data-msg-required`, `data-up-refusedtype`), so that nothing the user reads is fixed in English. The script writes no other text: a label, a hint or the words of a question belong to the markup and the language of the app (CODE-05). A new text goes into the table of its control in both languages, and its attribute into the header of the script and into the adoption guide.",
            RuleLevel.Should, Design,
            Why: "An app in another language or with other words must not need to patch the script. A text that is only in English, or only in a table that cannot be changed, is a text that one app cannot use.",
            Do: "<html lang=\"de\" data-dlg-ok=\"Verstanden\" data-up-refusedtype=\"{0}: Format nicht erlaubt.\">",
            Dont: "a string written into a function of the script, a key that exists in English only, a text that has no attribute to change it",
            Check: "Test (every key in both languages, every attribute documented)"),
        new("CODE-12", "CODE", "A drawn control keeps its native element",
            "A control that the script draws (a picker, a slider, a stepper, a rating, a code input, a file upload) is a wrapper around the native element that is validated, posted and reset: the real input keeps its `name`, `id`, `required`, `pattern`, `accept` and `disabled`, the keyboard and the events of a form (`input`, `change`), and where the script hides it, it is invisible in place and never `display: none`, so that it keeps the focus. Without the script the page is the native control, and the script adds only what the browser cannot do. A page that sets or reads a value uses the real input or `MatUi.<control>` and never the parts that the script drew: they may change from one version to the next (docs/VERSIONING.md).",
            RuleLevel.Should, Design,
            Why: "A drawn control that replaces the native one has to rebuild the keyboard, the form, the validation and the screen reader, and gets some of it wrong. A native element underneath keeps all of it, and a page without the script still works.",
            Do: "<div class=\"mat-slider\" data-slider><input class=\"mat-slider__input\" type=\"range\" id=\"vol\" name=\"vol\"></div>",
            Dont: "a div that posts nothing, display: none on the real input, a page that reads the value from the thumb that the script drew",
            Check: "Test (the markup, script and CSS contract of each control) and browser"),
        new("CODE-13", "CODE", "The names of the script: attributes, events and the API",
            "Behaviour is switched on by a `data-*` attribute named after what it does (`data-confirm`, `data-picker`, `data-tree-filter`), never by a class and never by an inline handler. An event that the script sends is `mat:<noun>-<verb>` (`mat:upload-change`, `mat:rating-change`, `mat:item-action`), is sent on the element it is about, carries what it says in `detail` and is cancelable where a page can stop what follows (`mat:schedule-select`, `mat:otp-complete`). The public API is `window.MatUi` with one object for each control (`MatUi.tree.setChildren`, `MatUi.upload.setProgress`), and `MatUi.refresh(scope)` wires markup that was added later. The header of `matui.js` documents the attributes, events and functions that an app may rely on; one that is not written down there or in the catalogue is not part of that contract (docs/VERSIONING.md).",
            RuleLevel.Should, Design,
            Why: "An app can only depend on what has a name that it can predict and a place where it is written down. The same shape for every control means that a new control is learned in a minute.",
            Do: "document.addEventListener('mat:upload-change', e => ...); MatUi.upload.setProgress(el, file, 40)",
            Dont: "an event called uploadDone, a behaviour that a class switches on, a function on window that is not in the header of the script",
            Check: "Test (every attribute of the header is handled, the documented API exists, no browser dialog) and review"),
        new("CODE-14", "CODE", "A sign-in is locked per name and address, headers come from known proxies",
            "A sign-in that fails is slowed down and counted per name and per address, so that one person cannot lock another out by guessing a name from somewhere else; after a few failures that pair is locked out for a short time. The message is one sentence whatever was wrong (the name, the password, a disabled account), and a name that does not exist is counted and delayed like one that does. The address that is counted is the one of the connection: `X-Forwarded-For`, `-Proto` and `-Host` are believed only from a proxy that is known (by default loopback and the private networks; `MATDESIGN_TRUSTED_PROXIES` narrows it, or says `none`), and then only the last entry that the proxy added, because what the client wrote itself stands before it. A setting that cannot be read stops the start with a message and never means everybody.",
            RuleLevel.Should, Design,
            Why: "Without a limit a password can be guessed. Without a proxy that is known anybody can write a header and start the count again at every try, which is how the lock-out of this site could once be started over.",
            Do: "MATDESIGN_TRUSTED_PROXIES=172.18.0.2, 10.0.0.0/8",
            Dont: "reading X-Forwarded-For from any sender, a message that says whether the name or the password was wrong, an empty setting that means everybody",
            Check: "Test (the lock-out, the trusted proxies) and review"),
        new("CODE-15", "CODE", "A change is finished when it is written down and checked",
            "A control, an option or a rule is finished when it is written down where it is looked for and checked by code where code can check it, in the same commit. The rule is in the rulebook with its reason and the way it is checked, and has a line in the changelog of the rulebook; the control has a live example with its notes and the rules it follows in the catalogue (CODE-07); an attribute, an event or a function is in the header of the script; what an app has to do is in the adoption guide; and what an app can see is a line under Unreleased in the changelog of the toolkit. The check is a unit test that reads the CSS, the script and the markup and crawls the site, and a browser check for what only a browser shows (a hit area, a drawer, a focus ring): reading a script proves little. A rule that names a test names one that exists.",
            RuleLevel.Should, Design,
            Why: "The rules are the product: what is not written where it is looked for is not known, and what is not checked drifts. A pull request that changes src/MatUi without a line in the changelog already fails; the rest is the same habit.",
            Do: "RuleBook.cs, RuleChangeEntries.cs, the catalogue, the header of matui.js, ADOPTING.md, CHANGELOG.md and the test, in one commit",
            Dont: "a rule whose check says Test and no test reads it, a control without an example in the catalogue, a change of a rule without a line in the changelog of the rulebook",
            Check: "Test (every component names rules, the changelog of the rulebook, a pull request that changes src/MatUi needs a line in CHANGELOG.md) and review"),
    ];

    public static Rule? Get(string id) => All.FirstOrDefault(r => r.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public static IEnumerable<Rule> In(string areaId) => All.Where(r => r.Area == areaId);
}
